//! 🧾️ Original JSON callback recovery retains its actual cursor and output owner.
use super::*;
use std::cell::Cell;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value::native_encoding::{NativeEncodeConstructionIssuer,NativeEncodeConstructionRecipient,NativeEncodeRetirementRecipient,NativeEncodeWorkIssuer,NativeEncodeWorkRecipient};
struct Physical<'a>{grant:RetainedCloneGrant,target:usize,calls:&'a Cell<usize>,armed:&'a Cell<bool>,received:&'a Cell<RetainedCloneProgress>}
impl NativeEncodeConstructionRecipient for Physical<'_>{fn submitted(&self)->RetainedCloneProgress{self.received.get()}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,_:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{self.calls.set(self.calls.get()+1);self.received.set(self.received.get().checked_add(progress)?);if progress.retained_capacity_bytes==self.target&&!self.armed.replace(true){panic!("original JSON receipt callback")};Ok(())}}
struct Work(u64);impl NativeEncodeWorkRecipient for Work{fn admits(&mut self,_:u64,additional:u64)->Result<bool,ValueError>{Ok(additional<=self.0)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.0-=actual;Ok(())}}
#[test]
fn original_json_frame_refuses_wrong_authority_then_recovers_without_repost(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(serde_json::to_string(&f["source"]).unwrap(),f["expected"].as_str().unwrap());let source=DslValue::Null;let target=semio_framework_pack_json::JsonBorrowedWriteCursor::new().normal_step_demands(&BorrowedJson(&source)).unwrap().capacity_bytes;let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<22,maximum_release_bytes:1<<22,maximum_depth:256};let calls=Cell::new(0);let wrong_calls=Cell::new(0);let received=Cell::new(RetainedCloneProgress::default());let wrong_received=Cell::new(RetainedCloneProgress::default());let armed=Cell::new(false);let wrong_armed=Cell::new(false);let mut physical=Physical{grant,target,calls:&calls,armed:&armed,received:&received};let mut wrong=Physical{grant,target,calls:&wrong_calls,armed:&wrong_armed,received:&wrong_received};let mut work=Work(f["work"].as_u64().unwrap());let mut wi=NativeEncodeWorkIssuer::new();let mut pi=NativeEncodeConstructionIssuer::new();let mut wrong_pi=NativeEncodeConstructionIssuer::new();let mut callback=|_|true;let mut retirement=NativeEncodeRetirementRecipient::new();let identity=retirement.identity();let wrong_identity=NativeEncodeRetirementRecipient::new().identity();let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut callback);native.install_retirement_recipient(&mut retirement).unwrap();let mut output=None;
 {let mut pl=pi.loan(&mut physical);let mut wl=wi.loan(&mut work);native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||write_json(&source,&mut owner,&mut output)));assert!(result.is_err());assert!(armed.get());drop(owner);let turn=native.close_retirement_recipient(grant);if let Err(failure)=turn.result{let failure=semio_framework_io_control::NativeSnapshotFailure::from(failure);let mut paid=semio_framework_value::retirement::controlled::ControlledRetirement::new(failure).ok().unwrap();for _ in 0..4096{if paid.terminal_is_empty(){break}paid.step(grant).unwrap();}assert!(paid.terminal_is_empty());}assert!(native.has_retirement_owner());Ok::<_,ValueError>(())})).unwrap();}assert!(native.has_retirement_owner());assert!(output.is_none());let original_calls=calls.get();
 {let mut pl=wrong_pi.loan(&mut wrong);let mut wl=wi.loan(&mut work);native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{let wrong_retirement=native.visit_effect_original::<JsonEncodeFrame,crate::lifted_serialization::SnapshotReceivingOutput<semio_framework_io_schema::IoPayload>>(wrong_identity,&mut |_,_|panic!("wrong retirement visitor"));assert!(wrong_retirement.is_err());let mut response=Some(Ok(()));let visited=native.visit_effect_original::<JsonEncodeFrame,crate::lifted_serialization::SnapshotReceivingOutput<semio_framework_io_schema::IoPayload>>(identity,&mut |frame,recovery|{let frame=frame.as_mut().unwrap();assert!(!semio_framework_value::retirement::RetireOwned::retirement_ready(frame));assert!(frame.settlement.as_mut().unwrap().recover_post(recovery,false,&mut response).is_err());});assert!(visited?);assert!(response.is_some());Ok::<_,ValueError>(())})).unwrap();}assert_eq!(wrong_calls.get(),0);assert_eq!(calls.get(),original_calls);
 {let mut pl=pi.loan(&mut physical);let mut wl=wi.loan(&mut work);native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{let visited=native.visit_effect_original::<JsonEncodeFrame,crate::lifted_serialization::SnapshotReceivingOutput<semio_framework_io_schema::IoPayload>>(identity,&mut |frame,recovery|{let frame=frame.as_mut().unwrap();let state=frame.settlement.as_mut().unwrap();state.recover_post(recovery,false,&mut Some(Ok(()))).unwrap();state.settle_retained(recovery).unwrap();let receipt=semio_framework_io_control::NativeSnapshotEncodeSettlement::take_receipt(&mut frame.settlement).unwrap();assert!(frame.writer.acknowledge_posted_turn(receipt).is_ok());});assert!(visited?);assert_eq!(calls.get(),original_calls);for _ in 0..100000{if !native.has_retirement_owner(){break}let turn=native.close_retirement_recipient(grant);let _step=turn.result.unwrap();}assert!(!native.has_retirement_owner());Ok::<_,ValueError>(())})).unwrap();}
}

#[test]
fn original_json_receipts_cover_the_published_value_and_parent_wallet(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let source=DslValue::Null;let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<22,maximum_release_bytes:1<<22,maximum_depth:256};let calls=Cell::new(0);let received=Cell::new(RetainedCloneProgress::default());let armed=Cell::new(false);let mut physical=Physical{grant,target:usize::MAX,calls:&calls,armed:&armed,received:&received};let mut work=Work(fixture["work"].as_u64().unwrap());let mut pi=NativeEncodeConstructionIssuer::new();let mut wi=NativeEncodeWorkIssuer::new();let mut pl=pi.loan(&mut physical);let mut wl=wi.loan(&mut work);let mut callback=|_|true;let mut retirement=NativeEncodeRetirementRecipient::new();let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut callback);native.install_retirement_recipient(&mut retirement).unwrap();let mut output=None;
 native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let turn=write_json(&source,&mut owner,&mut output);assert!(turn.result.is_ok());assert!(turn.work>0);assert_eq!(owner.progress(),received.get());assert!(matches!(&output,Some(Ok(semio_framework_io_schema::IoPayload::Text(text))) if text==fixture["expected"].as_str().unwrap()));drop(owner);for _ in 0..100000{if !native.has_retirement_owner(){break}native.close_retirement_recipient(grant).result.unwrap();}assert!(!native.has_retirement_owner());Ok::<_,ValueError>(())})).unwrap();let mut paid=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).ok().unwrap();for _ in 0..100000{if paid.terminal_is_empty(){break}paid.step(grant).unwrap();}assert!(paid.terminal_is_empty());
}
